$p='Source/Renderer/shadowmap.h'
$s=[IO.File]::ReadAllText((Join-Path (Get-Location) $p))
$s=$s.Replace('std::vector<DirectX::XMFLOAT3> vertices;','struct Vertex { DirectX::XMFLOAT3 position; float u,v; };'+"`n"+'    struct Batch { unsigned first,count; ComPtr<ID3D11ShaderResourceView> mask; };'+"`n"+'    std::vector<Vertex> vertices; std::vector<Batch> batches;')
$s=$s.Replace('ComPtr<ID3D11VertexShader> shader;','ComPtr<ID3D11VertexShader> shader;'+"`n"+'    ComPtr<ID3D11PixelShader> maskShader; ComPtr<ID3D11SamplerState> maskSampler;'+"`n"+'    bool attempted=false,ready=false;')
$s=$s.Replace('vertices.clear();return valid;','vertices.clear();batches.clear();return valid;')
$s=$s.Replace('if(shader)return true;','if(attempted)return ready; attempted=true;')
$s=$s.Replace('const char* source="cbuffer Matrix:register(b0){row_major float4x4 transform;} float4 VS(float3 p:POSITION):SV_Position{return mul(float4(p,1),transform);}";', 'const char* source="cbuffer Matrix:register(b0){row_major float4x4 transform;} struct V { float4 p:SV_Position; float2 uv:TEXCOORD0; }; V VS(float3 p:POSITION,float2 uv:TEXCOORD0){V o;o.p=mul(float4(p,1),transform);o.uv=uv;return o;} Texture2D mask:register(t0);SamplerState samp:register(s0);void PS(V i){clip(mask.Sample(samp,i.uv).a-.5);}";')
$s=$s.Replace('D3D11_INPUT_ELEMENT_DESC e{"POSITION",0,DXGI_FORMAT_R32G32B32_FLOAT,0,0,D3D11_INPUT_PER_VERTEX_DATA,0};','D3D11_INPUT_ELEMENT_DESC e[]={{"POSITION",0,DXGI_FORMAT_R32G32B32_FLOAT,0,0,D3D11_INPUT_PER_VERTEX_DATA,0},{"TEXCOORD",0,DXGI_FORMAT_R32G32_FLOAT,0,12,D3D11_INPUT_PER_VERTEX_DATA,0}};')
$s=$s.Replace('CreateInputLayout(&e,1,','CreateInputLayout(e,2,')
$s=$s.Replace('D3D11_TEXTURE2D_DESC td{};', 'code.Reset();error.Reset();'+"`n"+'        hr=D3DCompile(source,strlen(source),"Shadow mask",nullptr,nullptr,"PS","ps_4_0",0,0,&code,&error);'+"`n"+'        if(FAILED(hr) || FAILED(device->CreatePixelShader(code->GetBufferPointer(),code->GetBufferSize(),nullptr,&maskShader)))return false;'+"`n"+'        D3D11_SAMPLER_DESC sampler{};sampler.Filter=D3D11_FILTER_MIN_MAG_MIP_LINEAR;sampler.AddressU=sampler.AddressV=sampler.AddressW=D3D11_TEXTURE_ADDRESS_WRAP;sampler.MaxLOD=0;'+"`n"+'        if(FAILED(device->CreateSamplerState(&sampler,&maskSampler)))return false;'+"`n"+'        D3D11_TEXTURE2D_DESC td{};')
$s=$s.Replace('return SUCCEEDED(device->CreateRasterizerState(&rd,&raster));','ready=SUCCEEDED(device->CreateRasterizerState(&rd,&raster));return ready;')
$s=$s.Replace('XMLoadFloat3(&v),view','XMLoadFloat3(&v.position),view').Replace('vertices.size()*sizeof(XMFLOAT3)','vertices.size()*sizeof(Vertex)').Replace('stride=sizeof(XMFLOAT3)','stride=sizeof(Vertex)')
$s=$s.Replace('gpu->PSSetShader(nullptr,nullptr,0);gpu->Draw(unsigned(vertices.size()),0);return true;', 'gpu->PSSetSamplers(0,1,maskSampler.GetAddressOf());'+"`n"+'        for(const auto& batch:batches){auto* mask=batch.mask.Get();gpu->PSSetShaderResources(0,1,&mask);gpu->PSSetShader(mask?maskShader.Get():nullptr,nullptr,0);gpu->Draw(batch.count,batch.first);}'+"`n"+'        gpu->PSSetShaderResources(0,4,empty);return true;')
[IO.File]::WriteAllText((Join-Path (Get-Location) $p),$s)
